INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 12, 'theory', 'Квиз: сеть контейнера своими руками');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 12, 0, 'Из пространства ping шлюза моста проходит, а ping 8.8.8.8 пишет «Network is unreachable». Чего не хватает?', '["Правила MASQUERADE на хосте", "Маршрута по умолчанию внутри пространства", "Значения ip_forward=1 на хосте", "Включённого интерфейса lo на хосте"]', 1, 'Сообщение возникает, когда для адреса нет подходящего маршрута. Шлюз лежит в подключённой сети и доступен по маршруту сети, а внешний адрес требует default route внутри пространства. Пересылка и маскарад нужны позже, на хосте.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 12, 1, 'tcpdump -n на внешнем интерфейсе хоста показывает запросы ping с источником 10.200.0.2 и никаких ответов. Что делать?', '["Включить ip_forward, иначе пакеты не выйдут", "Добавить в пространство второй конец veth", "Добавить правило MASQUERADE для подсети в nat/postrouting", "Перезапустить tcpdump с ключом -e"]', 2, 'Раз пакеты уже вышли, пересылка работает. Но частный адрес 10.200.0.2 в интернете не маршрутизируется, поэтому ответов нет: источник нужно подменить адресом хоста.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 12, 2, 'В строке conntrack исходный набор src=10.200.0.2 dst=203.0.113.9, ответный src=203.0.113.9 dst=192.168.1.10. Что это значит?', '["Сработала подмена источника: клиент выглядит для сервера как 192.168.1.10", "Сработала подмена назначения: сервер на самом деле 192.168.1.10", "Нат не применялся, это обычное соединение", "Соединение закрыто"]', 0, 'Адрес получателя в ответном наборе — это то, как внешний сервер видит клиента. Он не равен исходному источнику, значит адрес отправителя был заменён: так работает MASQUERADE.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 12, 3, 'В какой цепочке таблицы nat ставят правило DNAT для публикации порта, на который приходят пакеты снаружи?', '["POSTROUTING", "INPUT", "FORWARD", "PREROUTING"]', 3, 'Назначение нужно изменить до решения о маршрутизации, чтобы пакет ушёл в пространство, а не в локальный процесс хоста. DNAT допустим в PREROUTING и OUTPUT; POSTROUTING служит для подмены источника.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 12, 4, 'Один конец пары veth на хосте включён, а второй внутри пространства выключен. Что покажет включённый конец?', '["Пара работает: достаточно включить любой конец", "Пара удалена ядром автоматически", "Адрес пропадёт и появится снова при включении соседа", "Соединения нет: если любой конец выключен, пара не работает"]', 3, 'По справке veth(4), если любой из концов выключен, состояние канала пары — выключено. Включённый конец при этом обычно показывает NO-CARRIER. Поэтому включать нужно оба конца.');
